use crate::linting::expr_linter::Chunk;
use crate::{
    Token,
    expr::{Expr, SequenceExpr},
    linting::{ExprLinter, Lint, LintKind, Suggestion},
};

pub struct VerseVersus {
    expr: Box<dyn Expr>,
}

impl Default for VerseVersus {
    fn default() -> Self {
        let expr = SequenceExpr::word_set(&[
            "can", "will", "to", "would", "could", "should", "you", "we", "they", "who", "not",
            "never", "are", "were", "am", "is", "was", "be", "been",
        ])
        .t_ws()
        .then_word_set(&["verse", "verses", "versed", "versing"])
        .t_ws()
        .then_word_set(&[
            "the", "a", "an", "your", "my", "his", "her", "their", "our", "it", "him", "them",
            "me", "us", "each", "every", "other", "another", "against", "computer", "bot",
        ]);
        Self {
            expr: Box::new(expr),
        }
    }
}

impl ExprLinter for VerseVersus {
    type Unit = Chunk;

    fn expr(&self) -> &dyn Expr {
        self.expr.as_ref()
    }

    fn match_to_lint(&self, toks: &[Token], src: &[char]) -> Option<Lint> {
        let tok = toks.get(2)?;
        Some(Lint {
            span: tok.span,
            lint_kind: LintKind::Usage,
            suggestions: ["face", "challenge", "play against", "compete against"]
                .iter()
                .map(|s| {
                    Suggestion::replace_with_match_case(
                        s.chars().collect(),
                        tok.span.get_content(src),
                    )
                })
                .collect(),
            message: "`Versus` is a preposition, not a verb. Use a verb such as `face` or `play against` instead.".to_owned(),
            ..Default::default()
        })
    }

    fn description(&self) -> &str {
        "Flags `verse` used as a verb in place of the preposition `versus`."
    }
}

#[cfg(test)]
mod tests {
    use super::VerseVersus;
    use crate::linting::tests::{assert_lint_count, assert_no_lints};

    #[test]
    fn flags_verse() {
        assert_lint_count(
            "You can verse the computer.",
            VerseVersus::default(),
            1,
        );
    }

    #[test]
    fn allows_noun() {
        assert_no_lints("She read a verse aloud.", VerseVersus::default());
    }
}

